    'path': 'parse.py',
    'old_string': '''        # make sure we don't collide ("a.b" colliding with "a_b")
        n = 1
        while group in self._group_to_name_map:
            n += 1
            if '.' in field:
                group = field.replace('.', '_' * n)
            elif '_' in field:
                group = field.replace('_', '_' * n)
            else:
                raise KeyError('duplicated group name %r' % (field,))''',
    'new_string': '''        # make sure we don't collide ("a.b" colliding with "a_b", etc.)
        n = 1
        while group in self._group_to_name_map:
            n += 1
            if '.' in field:
                group = field.replace('.', '_' * n)
            elif '_' in field or '-' in field:
                group = field.replace('_' if '_' in field else '-', '_' * n)
            else:
                raise KeyError('duplicated group name %r' % (field,))'''
})
